/* HeartSteps — interactive, local-only university project prototype.
   No external APIs, medical devices, real AI models, cloud sync, or NHS connection.
   All features run in the user's browser and persist through localStorage. */
(() => {
'use strict';
const STORAGE_KEY = 'heartsteps-prototype-v1';
const today = () => localDate(new Date());
const localDate = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const fromDate = d => new Date(`${d}T12:00:00`);
const daysBefore = n => { const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-n);return localDate(d);};
const readableDate = date => fromDate(date).toLocaleDateString('en-GB',{day:'numeric',month:'short'});
const dayName = date => fromDate(date).toLocaleDateString('en-GB',{weekday:'short'});
const escapeHtml = x => String(x??'').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clamp = (n,min,max)=>Math.min(max,Math.max(min,n));
const randId = () => String(Date.now())+'-'+Math.random().toString(36).slice(2,8);
const defaults = () => ({profile:{name:'',age:null,goal:30},food:[],activity:[],meds:[],alcohol:[],community:{joined:false,notes:[]},demo:false});
function sanitizeStore(p){const d=defaults();if(!p||typeof p!=='object')return d;return {profile:{name:String(p.profile?.name||'').slice(0,35),age:Number.isInteger(+p.profile?.age)&&+p.profile.age>=1?+p.profile.age:null,goal:clamp(Number(p.profile?.goal)||30,5,180)},food:Array.isArray(p.food)?p.food.slice(-250):[],activity:Array.isArray(p.activity)?p.activity.slice(-500):[],meds:Array.isArray(p.meds)?p.meds.slice(-30):[],alcohol:Array.isArray(p.alcohol)?p.alcohol.slice(-250):[],community:{joined:!!p.community?.joined,notes:Array.isArray(p.community?.notes)?p.community.notes.slice(-100):[]},demo:!!p.demo};}
function readStore(){try{return sanitizeStore(JSON.parse(localStorage.getItem(STORAGE_KEY)));}catch{return defaults();}}
let state=readStore();let view='dashboard',swap=null,foodQuery='',toastTimeout=null,communityTab='feed';
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{notify('Could not save locally; check your browser storage settings.');}}
function notify(s){let t=document.getElementById('toast');t.textContent=s;t.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>t.classList.remove('show'),3400);}
function mutate(fn,message){fn();save();render();if(message)notify(message);}
const svgPaths={
 heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',
 pulse:'<path d="M2 12h4l3-7 5 14 3-7h5"/>',home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1Z"/><path d="M9 21v-7h6v7"/>',
 food:'<path d="M4 3v7a4 4 0 0 0 8 0V3M8 3v18M17 3v18M17 3c5 1 5 7 0 9"/>',
 activity:'<circle cx="12" cy="12" r="9"/><path d="m12 5-4 8h4l-1 6 5-9h-4l1-5"/>',
 medicine:'<path d="m9 3 12 12a4 4 0 0 1-6 6L3 9a4.2 4.2 0 0 1 6-6Z"/><path d="m7 13 6-6"/>',
 community:'<path d="M16 20v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 20v-2a4 4 0 0 0-3-3.9M16 3.1a4 4 0 0 1 0 7.8"/>',
 book:'<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2Z"/>',
 settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.87l.06.06-2 2-.07-.06A1.7 1.7 0 0 0 15.9 19a1.7 1.7 0 0 0-.9 1.6V21h-3v-.4a1.7 1.7 0 0 0-1-1.6 1.7 1.7 0 0 0-1.8.3l-.1.1-2-2 .07-.07A1.7 1.7 0 0 0 7.5 15a1.7 1.7 0 0 0-1.6-1H5v-3h.9A1.7 1.7 0 0 0 7.5 10a1.7 1.7 0 0 0-.33-1.8L7.1 8l2-2 .1.1A1.7 1.7 0 0 0 11 6.4a1.7 1.7 0 0 0 1-1.6V4h3v.8a1.7 1.7 0 0 0 .9 1.6 1.7 1.7 0 0 0 1.8-.3l.1-.1 2 2-.06.1A1.7 1.7 0 0 0 19.4 10a1.7 1.7 0 0 0 1.6 1h.9v3H21a1.7 1.7 0 0 0-1.6 1Z"/>',
 check:'<path d="m5 12 4 4L19 6"/>', plus:'<path d="M12 5v14M5 12h14"/>', arrow:'<path d="M4 12h16m-7-7 7 7-7 7"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>', shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/><path d="m9 12 2 2 4-4"/>',
 sparkles:'<path d="m12 3 2 6 6 2-6 2-2 6-2-6-6-2 6-2 2-6ZM19 18l1 2 2 1-2 1-1 2-1-2-2-1 2-1 1-2Z"/>',
 trophy:'<path d="M7 3h10v7a5 5 0 0 1-10 0V3ZM7 5H4v4a4 4 0 0 0 4 4M17 5h3v4a4 4 0 0 1-4 4M12 15v4M8 21h8"/>',
 download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>', trash:'<path d="M4 7h16M9 7V4h6v3m-9 0 1 14h10l1-14M10 11v6M14 11v6"/>',
 chevron:'<path d="m9 18 6-6-6-6"/>', message:'<path d="M21 12a8 8 0 0 1-8 8 9 9 0 0 1-4-.9L3 21l1.9-6A9 9 0 0 1 4 12a8 8 0 0 1 8-8 9 9 0 0 1 9 8Z"/>',
 edit:'<path d="m3 17 1 4 4-1L20 8a3 3 0 0 0-4-4L3 17Z"/>',
 calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',
 alert:'<path d="M12 3 2 21h20L12 3ZM12 9v5M12 18h.01"/>',
 lock:'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',
 target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
 glass:'<path d="M5 3h14l-2 11a5 5 0 0 1-10 0L5 3ZM12 19v2M8 21h8"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',
 pencil:'<path d="m3 21 4-.9L19 8a3 3 0 0 0-4-4L3 16.1 3 21Z"/>',
 external:'<path d="M13 4h7v7M20 4l-9 9M20 13v7H4V4h7"/>'};
function ic(name,size=19){return `<svg class="ic" viewBox="0 0 24 24" width="${size}" height="${size}" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${svgPaths[name]||svgPaths.heart}</svg>`;}
const routes=[['dashboard','Dashboard','home'],['food','Food swaps','food'],['activity','Activity','activity'],['meds','Medicines','medicine'],['community','Community','community'],['learn','Learn','book'],['settings','Settings','settings']];
const btn=(label,action,classes='btn',extra='')=>`<button type="button" class="${classes}" data-action="${action}" ${extra}>${label}</button>`;
const sectionHead=(title,subtitle='',link='',action='')=>`<div class="section-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${link?`<button class="section-link" type="button" data-action="${action}">${link} ${ic('chevron',14)}</button>`:''}</div>`;
const info=(content)=>`<div class="info-banner">${ic('info',18)}<div>${content}</div></div>`;
const empty=(emoji,title,description)=>`<div class="empty"><div class="empty-icon">${emoji}</div><h3>${title}</h3><p>${description}</p></div>`;
const navButton=([id,label,icon],mobile=false)=>`<button type="button" class="${mobile?'mobile-btn':'nav-btn'} ${view===id?'active':''}" data-nav="${id}" ${view===id?'aria-current="page"':''}>${ic(icon,19)}<span>${label}</span></button>`;
function shell(content){const first=state.profile.name.trim()?escapeHtml(state.profile.name.trim().split(' ')[0]):'Friend';return `<div class="app-shell"><aside class="sidebar" aria-label="Primary navigation"><div class="brand"><div class="brand-icon">${ic('pulse',29)}</div><div><div class="brand-text">heartsteps</div><small>Heart on Wheels</small></div></div><div class="sidebar-label">Your space</div><nav class="nav">${routes.map(r=>navButton(r)).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-mini"><span class="pill">${ic('shield',13)} Local-only demo</span><p>A healthier routine, one small step at a time.</p><button class="btn small cream" data-nav="learn">Learn about cholesterol ${ic('arrow',13)}</button></div><div class="nav-foot">Student concept · Not NHS affiliated</div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Heart on Wheels <span style="opacity:.45">/</span> ${routes.find(r=>r[0]===view)?.[1]}</div><div class="top-actions"><span class="prototype">Interactive prototype</span><button type="button" class="avatar" title="Profile settings" data-nav="settings" aria-label="Open profile settings">${escapeHtml(first[0].toUpperCase())}</button></div></header>${content}<footer class="foot"><span>HeartSteps · Student health promotion prototype</span><span>Educational support only · Not a diagnosis or emergency service</span></footer></main><nav class="bottom-nav" aria-label="Mobile navigation">${[routes[0],routes[1],routes[2],routes[3],routes[4]].map(r=>navButton(r,true)).join('')}<button type="button" class="mobile-btn ${['learn','settings'].includes(view)?'active':''}" data-nav="settings">${ic('settings')}<span>More</span></button></nav></div>`;}
function sumActivity(date){return state.activity.filter(a=>a.date===date).reduce((s,a)=>s+Math.max(0,Number(a.minutes)||0),0);}
function sumXP(){return state.activity.reduce((s,a)=>s+Math.max(0,Number(a.xp)||0),0)+(state.food.length*10);}
function streak(){let n=0;for(let i=0;i<365;i++){const date=daysBefore(i);if(sumActivity(date)>0)n++;else if(i===0)continue;else break;}return n;}
function thisWeek(){return Array.from({length:7},(_,i)=>daysBefore(6-i));}
function swapsThisWeek(){return state.food.filter(f=>f.date>=daysBefore(6)).length;}
function activityThisWeek(){return state.activity.filter(f=>f.date>=daysBefore(6)).reduce((s,a)=>s+Number(a.minutes||0),0);}
function medicineDue(){const t=new Date().toTimeString().slice(0,5);return state.meds.filter(m=>!m.takenDates?.includes(today())&&m.time<=t);}
function activityStats(){const mins=sumActivity(today());return {mins,goal:state.profile.goal,percentage:clamp(mins/state.profile.goal*100,0,100)};}
function heroArt(){return `<svg viewBox="0 0 180 180" width="180" role="img" aria-label="Illustrated heart with an activity pulse"><circle cx="90" cy="90" r="73" fill="#ffffff12"/><path d="M90 148C36 111 25 84 36 57 47 29 77 30 90 50c13-20 43-21 54 7 11 27 0 54-54 91Z" fill="#b8f0d6"/><path d="M42 93h28l13-25 15 49 15-26h25" stroke="#276d62" stroke-width="6" fill="none" stroke-linecap="round" stroke-linejoin="round"/><circle cx="141" cy="37" r="9" fill="#f9d8a8"/></svg>`;}
function weeklyGraph(){const week=thisWeek(),values=week.map(sumActivity),max=Math.max(state.profile.goal,...values,1);return `<div class="bar-area"><div class="week-bars" role="img" aria-label="Activity minutes across the last seven days: ${values.join(', ')}"><div style="position:absolute"></div>${week.map((d,i)=>`<div class="bar-col"><div class="bar ${values[i]?'':'empty'}" title="${escapeHtml(dayName(d))}: ${values[i]} min" style="height:${Math.max(3,values[i]/max*119)}px"></div><span>${escapeHtml(dayName(d))}</span></div>`).join('')}</div></div><div class="row-between"><span class="bar-label">Last 7 days</span><span class="badge gray">${activityThisWeek()} min total</span></div>`;}
const quests=[{id:'walk',emoji:'🚶',name:'A little fresh air',type:'Walking',minutes:10,xp:20,detail:'A relaxed 10-minute walk'},{id:'cycle',emoji:'🚲',name:'Get moving',type:'Cycling',minutes:15,xp:30,detail:'A comfortable 15-minute cycle'},{id:'dance',emoji:'🎵',name:'Move to music',type:'Dancing',minutes:20,xp:40,detail:'20 minutes of dancing your way'},{id:'stretch',emoji:'🧘',name:'Gentle movement',type:'Stretching',minutes:10,xp:20,detail:'10 minutes of gentle stretching'}];
function questCard(q){return `<div class="quest"><div class="quest-icon">${q.emoji}</div><div class="quest-info"><strong>${escapeHtml(q.name)}</strong><p>${escapeHtml(q.detail)}</p></div><span class="xp">+${q.xp} XP</span>${btn(`${ic('plus',14)} Log`, `quest:${q.id}`,'btn small outline')}</div>`;}
function nextMedCard(){const due=medicineDue(),next=state.meds.filter(m=>!m.takenDates?.includes(today())).sort((a,b)=>a.time.localeCompare(b.time))[0];return `<div class="card"><div class="card-title"><h3>💊 Medicine reminders</h3>${btn('View', 'nav:meds','btn small ghost')}</div>${state.meds.length?`<p class="small-text">${due.length?`<b>${due.length} reminder${due.length>1?'s':''} due.</b> Please check your prescribed schedule.`:next?`Next tracked time: <b>${escapeHtml(next.time)} — ${escapeHtml(next.name)}</b>`:'All tracked items marked for today.'}</p>`:empty('⏰','Nothing added yet','Track medicines already prescribed to you and mark them as taken.')}${btn(`${ic('plus',14)} Add medicine`,'nav:meds','btn small outline', 'style="margin-top:12px"')}</div>`;}
function dashboard(){const a=activityStats(),s=streak(),xp=sumXP(),name=state.profile.name.trim()?escapeHtml(state.profile.name.trim().split(' ')[0]):'there';return `<section class="hero"><div style="position:relative;z-index:1"><span class="eyebrow">Your wellness companion</span><h1>Small steps. A healthier heart.</h1><p>Hi ${name}! Build heart-healthy routines with smarter food choices, daily movement and progress you can actually see.</p>${btn(`Explore food swaps ${ic('arrow',17)}`,'nav:food','btn cream hero-action')}</div><div class="hero-art">${heroArt()}</div></section>${state.demo?`<div style="margin-top:13px">${info(`<strong>Sample data loaded.</strong> This activity is fictional for demonstration. ${btn('Clear sample','clear-demo','btn small outline')}`)}</div>`:''}<div class="stats"><div class="card stat"><div class="stat-icon mint">${ic('activity',20)}</div><div class="num mono">${a.mins}<small> / ${a.goal} min</small></div><div class="stat-label">Movement today</div><div class="stat-detail">${a.percentage>=100?'Daily goal reached 🎉':'Your chosen daily goal'}</div></div><div class="card stat"><div class="stat-icon peach">${ic('food',20)}</div><div class="num mono">${swapsThisWeek()}</div><div class="stat-label">Smart swaps this week</div><div class="stat-detail">Each choice adds 10 XP</div></div><div class="card stat"><div class="stat-icon purple">${ic('trophy',20)}</div><div class="num mono">${xp}<small> XP</small></div><div class="stat-label">Total progress points</div><div class="stat-detail">${s} day${s===1?'':'s'} active streak</div></div></div>${sectionHead('Your week','Track progress, not perfection.','Log activity','nav:activity')}<div class="split"><div class="col-stack"><div class="card"><div class="card-title"><h3>Movement over time</h3><span class="badge">${ic('pulse',13)} Every minute counts</span></div>${weeklyGraph()}</div><div class="card"><div class="card-title"><h3>Quick wins for today</h3><span class="badge orange">Earn XP</span></div>${quests.slice(0,2).map(questCard).join('')}</div></div><div class="col-stack"><div class="card"><div class="card-title"><h3>Daily movement goal</h3><span class="badge gray">Personal goal</span></div><div class="ring-wrap"><div class="ring" style="--fill:${a.percentage}%"><div class="ring-inner"><b>${Math.round(a.percentage)}%</b><small>complete</small></div></div><div><strong>${Math.max(0,a.goal-a.mins)} min to go</strong><p class="small-text" style="margin-top:6px">${a.percentage>=100?'Well done on reaching your chosen goal.':'A short walk or a little dancing can add up.'}</p>${btn('Add movement','nav:activity','btn small outline','style="margin-top:12px"')}</div></div></div>${nextMedCard()}</div></div>${sectionHead('Your next heart-healthy choice','Practical ideas that fit real life.')}<div class="content-grid"><div class="card"><h3>🥣 Try a simple food swap</h3><p class="small-text" style="margin-top:8px">Small, affordable changes to saturated fat and fibre intake can make a difference over time.</p><div class="button-row">${btn('Find a healthier swap','nav:food','btn')}${btn('Read cholesterol basics','nav:learn','btn outline')}</div></div><div class="card"><h3>🎯 Build consistency</h3><p class="small-text" style="margin-top:8px">Try a daily mini-challenge and collect XP. No guilt if you miss a day.</p><div class="button-row">${btn('See challenges','nav:activity','btn outline')}</div></div></div><div style="margin-top:18px">${info(`<strong>Your health, your choice.</strong> This prototype supports healthy habits; it cannot measure cholesterol, diagnose conditions or replace guidance from a pharmacist or GP.`)}</div>`;}
const swapLibrary=[
 {keywords:['butter','ghee'],from:'Butter or ghee',to:'Olive or rapeseed oil, or an unsaturated-fat spread',why:'Unsaturated fats can replace some saturated fat. Use modest portions of oils or spreads.',budget:'Budget tip: supermarket own-brand rapeseed oil is often good value.',emoji:'🫒'},
 {keywords:['bacon','sausage','salami','processed meat','pepperoni'],from:'Processed meats',to:'Beans, lentils, hummus or skinless chicken',why:'Replacing some processed, high-saturated-fat meat meals with pulses increases fibre.',budget:'Budget tip: tinned beans and dried lentils are inexpensive.',emoji:'🫘'},
 {keywords:['whole milk','full fat milk','full-fat milk','full cream milk'],from:'Whole milk',to:'Semi-skimmed or skimmed milk, or unsweetened fortified soya drink',why:'Lower-saturated-fat options can help reduce overall saturated fat intake.',budget:'Budget tip: supermarket own-brand semi-skimmed milk.',emoji:'🥛'},
 {keywords:['cheddar','cheese','cream cheese'],from:'Full-fat cheese',to:'Smaller portions, reduced-fat cheese or hummus',why:'Portion choices and lower-saturated-fat alternatives can help manage saturated fat.',budget:'Budget tip: use less strongly flavoured cheese for the same taste.',emoji:'🧀'},
 {keywords:['croissant','pastry','pastries','cake','biscuit','cookie','doughnut'],from:'Pastries, cakes or biscuits',to:'Porridge with fruit, oatcakes or unsalted nuts',why:'Oats contain soluble fibre; replacing frequently eaten high-saturated-fat snacks can help.',budget:'Budget tip: large bags of porridge oats are economical.',emoji:'🥣'},
 {keywords:['fried chicken','fried food','chips','fries'],from:'Frequently fried foods',to:'Oven-baked alternatives, with vegetables or salad',why:'Cooking methods and oil choice affect the total fat and energy in a meal.',budget:'Budget tip: home-cooked oven wedges from potatoes.',emoji:'🥔'},
 {keywords:['cereal','cornflakes','granola'],from:'Refined or sugary breakfast cereal',to:'Porridge oats topped with fruit',why:'Oats provide beta-glucan, a type of soluble fibre associated with lowering cholesterol as part of a healthy diet.',budget:'Budget tip: plain oats plus frozen berries.',emoji:'🍓'},
 {keywords:['red meat','beef','burger','lamb','mince'],from:'Fatty red meat',to:'Beans, lentils, tofu or leaner cuts in smaller portions',why:'Swapping some saturated-fat sources for plant proteins can improve the overall diet.',budget:'Budget tip: bulk out mince dishes with lentils.',emoji:'🥘'},
 {keywords:['chocolate','ice cream'],from:'Rich desserts or sweets',to:'Fruit, lower-fat yoghurt, or a smaller serving',why:'Portion size and frequency matter. Enjoy foods you like while making sustainable changes.',budget:'Budget tip: frozen fruit works well in yoghurt.',emoji:'🍨'},
 {keywords:['palm oil','coconut oil','coconut milk'],from:'Coconut or palm-based fats',to:'Rapeseed or olive oil where suitable',why:'These alternatives generally have less saturated fat than coconut or palm fats.',budget:'Budget tip: use small amounts of versatile own-brand oil.',emoji:'🌴'},
 {keywords:['white bread','white rice','white pasta'],from:'Refined grains',to:'Wholemeal bread, brown rice or wholewheat pasta',why:'Higher-fibre alternatives can support a heart-healthy eating pattern.',budget:'Budget tip: compare own-brand wholegrain options.',emoji:'🌾'},
 {keywords:['crisps','potato chips'],from:'Crisps',to:'Unsalted nuts, popcorn or sliced vegetables',why:'Choosing snacks with less salt and a healthier fat profile can support cardiovascular health.',budget:'Budget tip: air-popped popcorn made from kernels.',emoji:'🥜'},
 {keywords:['pizza'],from:'Cheesy takeaway pizza',to:'Homemade wholemeal-base pizza with vegetables and a little cheese',why:'A homemade version makes portions, salt and saturated fat easier to adjust.',budget:'Budget tip: use pitta bread as a mini pizza base.',emoji:'🍕'}
];
function findSwap(text){const q=text.toLowerCase().trim().replace(/\s+/g,' ');if(q.length<2)return null;let found=swapLibrary.find(item=>item.keywords.some(k=>q.includes(k)));if(found)return {...found,query:text,match:true};return {from:text,to:'Build a balanced meal with vegetables, fibre-rich wholegrains and an unsaturated-fat source',why:'The demo did not recognise this food. This is general education, not an analysis of the actual product or its ingredients. Check the saturated-fat and fibre information on the food label.',budget:'Budget tip: compare supermarket own-brand options and food labels.',emoji:'🥗',query:text,match:false};}
function foodPage(){const foodRows=[...state.food].reverse().slice(0,6);return `<div class="page-header"><div class="page-kicker">Food smarter, not stricter</div><h1>Simple swaps, big possibilities.</h1><p>Explore realistic options for everyday foods. Our prototype uses a reviewed food-swap library to illustrate the proposed AI assistant — no AI model or external service is connected.</p></div><div class="content-grid"><div class="col-stack"><div class="card"><div class="card-title"><h3>${ic('sparkles',19)} Smart swap assistant</h3><span class="badge">Demo guidance</span></div><form id="food-form"><div class="form-group"><label for="food-input">What food would you like an alternative for?</label><input id="food-input" name="query" class="input" maxlength="85" value="${escapeHtml(foodQuery)}" placeholder="e.g. butter, bacon, pastries" required></div><button class="btn" type="submit">Suggest a healthier swap ${ic('arrow',16)}</button></form><div class="examples" aria-label="Example foods">${['Butter','Bacon','Cheddar','Pastries','Pizza','Whole milk'].map(x=>`<button class="example-chip" data-food-example="${x}" type="button">${x}</button>`).join('')}</div>${swap?`<div class="swap-result" role="region" aria-label="Food swap suggestion"><span class="badge">${swap.match?'Matched food':'General suggestion'}</span><p class="swap-from">Instead of: <b>${escapeHtml(swap.from)}</b></p><div class="swap-to">${swap.emoji} ${escapeHtml(swap.to)}</div><p class="why">${escapeHtml(swap.why)}</p><div class="cost">💷 ${escapeHtml(swap.budget)}</div><div class="button-row">${btn(`${ic('check',16)} I chose this swap`,'save-swap','btn')}${btn('Try another','clear-swap','btn outline')}</div></div>`:''}</div><div class="card"><div class="card-title"><h3>My food-swap choices</h3><span class="badge gray">${state.food.length} logged</span></div>${foodRows.length?`<div class="history-list">${foodRows.map(f=>`<div class="history-row"><div class="hist-icon">🥗</div><div class="hist-main"><strong>${escapeHtml(f.to)}</strong><p>Instead of ${escapeHtml(f.from)}</p><time>${escapeHtml(readableDate(f.date))}</time></div>${btn(ic('trash',15),`delete-food:${f.id}`,'btn small ghost','aria-label="Remove food swap"')}</div>`).join('')}</div>`:empty('🥕','No swaps saved yet','Search for a food above and log an option you choose.')}</div></div><div class="col-stack"><div class="card"><h3>💚 Food changes that last</h3><p class="small-text" style="margin-top:10px">The goal isn't to ban foods. Try one or two changes you can enjoy and afford.</p><ul class="tip-list"><li>Replace some saturated fats with unsaturated fats.</li><li>Choose more oats, beans and other fibre-rich foods.</li><li>Compare nutrition labels and portion sizes.</li><li>Make adjustments for allergies or dietary needs.</li></ul></div><div class="card"><h3>🍽️ A balanced approach</h3><div class="mini-action"><div class="mini-ico">🫒</div><div><strong>Healthy fats</strong><p>Olive and rapeseed oil, nuts and seeds</p></div></div><div class="mini-action"><div class="mini-ico">🥣</div><div><strong>More fibre</strong><p>Oats, vegetables, beans and wholegrains</p></div></div><div class="mini-action"><div class="mini-ico">💧</div><div><strong>Everyday balance</strong><p>Choose water often; be mindful of alcohol</p></div></div></div>${info('<strong>Important:</strong> Food suggestions are educational, not individual clinical advice. This demo does not identify allergens or evaluate the nutrient content of scanned foods. Consult a pharmacist or dietitian for individual needs.')}</div></div>`;}
function activityPage(){const a=activityStats(),week=thisWeek();const rows=[...state.activity].reverse().slice(0,8);const alcoholWeek=state.alcohol.filter(x=>x.date>=daysBefore(6)).reduce((s,x)=>s+Number(x.units||0),0);return `<div class="page-header"><div class="page-kicker">Movement and motivation</div><h1>Your adventure, at your pace.</h1><p>Turn realistic activity goals into small daily challenges, build a streak and celebrate consistency. Choose activities suited to your abilities and health.</p></div><div class="stats" style="margin-top:0"><div class="card stat"><div class="stat-icon mint">${ic('activity',19)}</div><div class="num">${a.mins}<small> min</small></div><div class="stat-label">Activity today</div></div><div class="card stat"><div class="stat-icon purple">${ic('trophy',19)}</div><div class="num">${streak()}<small> days</small></div><div class="stat-label">Current streak</div></div><div class="card stat"><div class="stat-icon peach">${ic('sparkles',19)}</div><div class="num">${sumXP()}<small> XP</small></div><div class="stat-label">Points earned</div></div></div>${sectionHead('7-day movement path','Each day with activity lights up a step.')}<div class="card"><div class="mission-path">${week.map(date=>`<div class="path-node ${sumActivity(date)?'complete':''} ${date===today()?'today':''}"><div class="path-dot">${sumActivity(date)?ic('check',16):date===today()?'•':'·'}</div><span>${escapeHtml(dayName(date))}</span></div>`).join('')}</div><div class="row-between" style="margin-top:22px"><span class="small-text">${a.mins} of ${a.goal} minutes today</span><span class="badge">${Math.round(a.percentage)}% goal</span></div><div class="progress-track" style="margin-top:9px"><div class="progress-fill" style="width:${a.percentage}%"></div></div></div>${sectionHead('Choose a mini-challenge','Log a challenge once completed to earn XP.')}<div class="activity-list">${quests.map(q=>`<div class="act-card"><div class="emoji">${q.emoji}</div><b>${escapeHtml(q.name)}</b><p>${escapeHtml(q.detail)}</p><div class="row-between"><span class="xp">+${q.xp} XP</span>${btn('Log it',`quest:${q.id}`,'btn small outline')}</div></div>`).join('')}</div>${sectionHead('Log your own activity')}<div class="content-grid"><div class="col-stack"><div class="card"><form id="activity-form"><div class="input-row"><div class="form-group"><label for="act-type">Activity</label><select name="type" class="select" id="act-type" required><option>Walking</option><option>Cycling</option><option>Dancing</option><option>Swimming</option><option>Gardening</option><option>Stretching</option><option>Other movement</option></select></div><div class="form-group"><label for="act-minutes">Minutes</label><input class="input" id="act-minutes" type="number" name="minutes" min="1" max="300" value="15" required></div></div><div class="form-group"><label for="act-date">Date</label><input class="input" id="act-date" type="date" name="date" min="${daysBefore(90)}" max="${today()}" value="${today()}" required></div><div class="form-group"><label for="act-note">Optional note</label><input class="input" id="act-note" name="note" maxlength="110" placeholder="How did it feel?"></div><button type="submit" class="btn">${ic('plus',16)} Log activity</button></form></div><div class="card"><div class="card-title"><h3>Recent movement</h3><span class="badge gray">${state.activity.length} logged</span></div>${rows.length?`<div class="history-list">${rows.map(a=>`<div class="history-row"><div class="hist-icon">🚶</div><div class="hist-main"><strong>${escapeHtml(a.type)} · ${Number(a.minutes)} min</strong><p>${escapeHtml(a.note||'Small steps count.')}</p><time>${readableDate(a.date)} · +${a.xp} XP</time></div>${btn(ic('trash',14),`delete-activity:${a.id}`,'btn small ghost','aria-label="Remove logged activity"')}</div>`).join('')}</div>`:empty('🏃','Your story starts here','Record your first movement session.')}</div></div><div class="col-stack"><div class="card"><h3>🍹 Optional alcohol tracker</h3><p class="small-text" style="margin:7px 0 17px">Record the number of UK alcohol units consumed. Keep this private; there is no judgement.</p><strong class="num-highlight">${Number(alcoholWeek.toFixed(1))}</strong><span class="small-text"> units recorded in the last 7 days</span><div class="hr"></div><form id="alcohol-form"><div class="input-row"><div class="form-group"><label for="alc-date">Date</label><input class="input" id="alc-date" type="date" name="date" min="${daysBefore(90)}" max="${today()}" value="${today()}" required></div><div class="form-group"><label for="alc-units">UK units</label><input class="input" id="alc-units" name="units" type="number" min="0.1" max="100" step="0.1" placeholder="e.g. 2" required></div></div><button class="btn small" type="submit">Log units</button></form><div class="hr"></div>${state.alcohol.length?`<div class="history-list">${[...state.alcohol].reverse().slice(0,4).map(x=>`<div class="history-row"><div class="hist-icon">🍷</div><div class="hist-main"><strong>${escapeHtml(x.units)} units</strong><time>${readableDate(x.date)}</time></div>${btn(ic('trash',13),`delete-alcohol:${x.id}`,'btn small ghost','aria-label="Remove alcohol entry"')}</div>`).join('')}</div>`:''}<p class="notes" style="margin-top:10px">NHS advice: if you drink regularly, keep to no more than 14 units per week, spread across several days. This tracker is not treatment advice.</p></div>${info('<strong>Exercise safely.</strong> Choose activities appropriate for your mobility and health. Stop and seek medical advice if you experience concerning symptoms. Activity levels do not indicate cholesterol levels.')}</div></div>`;}
function medsPage(){const due=medicineDue();const all=[...state.meds].sort((a,b)=>a.time.localeCompare(b.time));return `<div class="page-header"><div class="page-kicker">Supporting your routine</div><h1>Medicines, made easier to track.</h1><p>Keep a simple record of medicines you have already been prescribed. HeartSteps does not advise on starting, stopping or changing medication.</p></div><div class="content-grid"><div class="col-stack"><div class="card"><div class="card-title"><h3>Today's medicine checklist</h3><span class="badge ${due.length?'orange':'gray'}">${due.length?`${due.length} due now`:'Your schedule'}</span></div>${all.length?all.map(m=>`<div class="med-item"><span class="med-time">${escapeHtml(m.time)}</span><div class="med-name"><b>${escapeHtml(m.name)}</b><p>${m.takenDates?.includes(today())?'Marked taken today':'Follow your prescribed instructions'}</p></div>${btn(m.takenDates?.includes(today())?`${ic('check',15)} Taken`:'Mark taken',`toggle-med:${m.id}`,`tickbox ${m.takenDates?.includes(today())?'checked':''}`)}${btn(ic('trash',14),`delete-med:${m.id}`,'btn small ghost',`aria-label="Remove ${escapeHtml(m.name)} reminder"`)}</div>`).join(''):empty('💊','No medicines added','Add medications you already take, if you find tracking useful.')}</div><div class="card"><h3>Add a tracking reminder</h3><p class="small-text" style="margin:7px 0 15px">Track only an existing prescription or medicine you already use.</p><form id="med-form"><div class="form-group"><label for="med-name">Medicine name</label><input id="med-name" class="input" name="name" maxlength="70" placeholder="As listed on your prescription" required></div><div class="form-group"><label for="med-time">Time you usually take it</label><input id="med-time" class="input" type="time" name="time" value="09:00" required></div><button type="submit" class="btn">${ic('plus',16)} Add reminder</button></form></div></div><div class="col-stack"><div class="card"><h3>🔔 About notifications</h3><p class="small-text" style="margin-top:10px">This version shows reminders <strong>inside the app while it is open</strong>. It cannot send guaranteed background or phone notifications.</p><div class="hr"></div><p class="small-text">A future production version could use secure scheduled notifications and an accessible medication checklist, following clinical and data-protection review.</p></div><div class="callout"><strong>Medication safety</strong><p>Never use this tracker to decide which medicine to take or how much. If you miss a dose or have questions, check the patient leaflet or ask your pharmacist. Do not double doses based on this app.</p></div>${info('<strong>Private by design for this demo.</strong> Medicine entries are stored in this browser only. There is no NHS account, clinician connection or automatic data sharing.')}</div></div>`;}
const demoPosts=[{name:'Maya · example',age:'Illustrative post',initial:'M',text:'I tried porridge with frozen berries for breakfast this week. It was easier on my budget than I expected! 🥣'},{name:'Sam · example',age:'Illustrative post',initial:'S',text:'A 10-minute walk after lunch feels achievable for me. Trying to focus on consistency, not speed.'},{name:'Pat · example',age:'Illustrative post',initial:'P',text:'We swapped one mince dinner for lentil bolognese. Everyone liked it — sharing the idea! 🫘'}];
function communityPage(){const allowed=Number(state.profile.age)>=25;return `<div class="page-header"><div class="page-kicker">Together feels easier</div><h1>Encouragement makes a difference.</h1><p>Discover peer-support ideas, join an example group challenge and keep a private reflection journal. Community features in the proposed app are for people aged 25 and over.</p></div>${!allowed?`<div class="content-grid"><div class="card"><div class="stat-icon purple" style="width:54px;height:54px">${ic('lock',27)}</div><h2>Community demo: age 25+</h2><p style="margin:12px 0 18px">The student proposal restricts its community feature to people aged 25 or over. You can still use food swaps, movement, medicine tracking and education at any eligible age.</p><form id="community-age-form"><div class="form-group"><label for="community-age">Your age (no birth date required)</label><input class="input num-input" id="community-age" name="age" type="number" min="1" max="120" value="${state.profile.age??''}" required></div><button class="btn" type="submit">Confirm age</button></form></div><div class="card"><h3>🛡️ Safety by design</h3><p class="small-text" style="margin:13px 0">This prototype has no live users, chat servers or public posting. The sample messages are fictional. Your notes remain on this device.</p>${info('For a real social feature, identity protection, content moderation, safeguarding and secure accounts would be necessary.')}</div></div>`:`${sectionHead('Community space','Illustrative feed — not connected to real members.')}<div class="content-grid"><div class="col-stack"><div class="tab-row"><button type="button" class="tab ${communityTab==='feed'?'active':''}" data-action="community-tab:feed">Inspiration feed</button><button type="button" class="tab ${communityTab==='journal'?'active':''}" data-action="community-tab:journal">My private journal</button></div>${communityTab==='feed'?`<div class="card"><div class="card-title"><h3>Small changes, shared ideas</h3><span class="badge gray">Sample posts</span></div>${demoPosts.map(p=>`<div class="demo-post"><div class="post-header"><div class="post-avatar">${p.initial}</div><div><b>${escapeHtml(p.name)}</b><span>${escapeHtml(p.age)}</span></div></div><p>${escapeHtml(p.text)}</p></div>`).join('')}</div>`:`<div class="card"><h3>Your private reflection journal</h3><p class="small-text" style="margin:7px 0 14px">Write down a goal or achievement. Nothing you write is published.</p><form id="journal-form"><div class="form-group"><label for="journal-text">What's one step you're proud of?</label><textarea class="textarea" id="journal-text" name="note" maxlength="500" placeholder="Today, I..." required></textarea></div><button class="btn" type="submit">${ic('pencil',15)} Save private note</button></form><div class="hr"></div>${state.community.notes.length?`<div class="history-list">${[...state.community.notes].reverse().map(n=>`<div class="history-row"><div class="hist-icon">💭</div><div class="hist-main"><strong>${readableDate(n.date)}</strong><p>${escapeHtml(n.text)}</p></div>${btn(ic('trash',14),`delete-note:${n.id}`,'btn small ghost','aria-label="Delete journal note"')}</div>`).join('')}</div>`:empty('✍️','No notes yet','Your personal progress story belongs to you.')}</div>`}</div><div class="col-stack"><div class="card"><h3>🚶 The seven-day movement circle</h3><p class="small-text" style="margin:10px 0 16px">A sample group goal: aim for movement you enjoy on three days this week.</p><div class="row-between"><span class="badge">${thisWeek().filter(d=>sumActivity(d)>0).length} / 3 days logged</span>${state.community.joined?'<span class="badge purple">Joined</span>':''}</div><div class="progress-track" style="margin:15px 0"><div class="progress-fill" style="width:${clamp(thisWeek().filter(d=>sumActivity(d)>0).length/3*100,0,100)}%"></div></div>${btn(state.community.joined?'Leave challenge':'Join the challenge','community-join','btn outline')}${state.community.joined?'<p class="small-text" style="margin-top:12px">Activity logs count automatically towards this illustrative challenge.</p>':''}</div><div class="callout"><strong>Demo community, not live chat</strong><p>All member posts are fictional examples. Your reflections are private and remain on your device; no content is transmitted to other people.</p></div></div></div>`}`;}
const faqs=[
 ['What is high cholesterol?','Cholesterol is a fatty substance your body needs. Raised levels of some blood lipids, particularly LDL cholesterol, can increase the risk of cardiovascular disease over time.'],
 ['Can I feel if my cholesterol is high?','Usually not. High cholesterol often causes no symptoms. A blood test is needed to check lipid levels. Fitness, appearance and how you feel cannot rule it out.'],
 ['How is cholesterol checked?','A lipid blood test measures cholesterol components and may include triglycerides. A pharmacist or GP can discuss suitable testing and help interpret results with other risk factors.'],
 ['What everyday changes can help?','Depending on your circumstances, changes may include choosing unsaturated fats instead of some saturated fats, eating more fibre-rich foods, being physically active, avoiding smoking and limiting alcohol.'],
 ['Does a high result mean I need a statin?','Not automatically. Treatment depends on the lipid results, personal and family medical history, other risk factors and shared decisions with a qualified clinician. Do not start or stop medicines based on this app.'],
 ['What is QRISK3?','QRISK3 is a clinical tool used for appropriate patients to estimate ten-year cardiovascular disease risk. It needs detailed information and should be interpreted by a qualified professional. This prototype does not calculate QRISK3.'],
 ['Will this app lower my cholesterol?','An app cannot measure or guarantee changes in cholesterol. It can support healthier routines, but actual cholesterol change requires appropriately timed blood testing and clinical review.'],
 ['Can my pharmacist see my data?','Not automatically. This demo only stores entries in the current browser. You can download a file and choose whether to show it to a clinician. No NHS integration is present.']
];
function learnPage(){return `<div class="page-header"><div class="page-kicker">Understand your heart health</div><h1>Knowledge is a good first step.</h1><p>Clear, practical answers about cholesterol and the decisions you can make with your pharmacist or GP.</p></div><div class="content-grid"><div class="col-stack"><div class="card"><div class="card-title"><h3>Common questions</h3><span class="badge">NHS-aligned themes</span></div><div class="topic-list">${faqs.map(([q,a],i)=>`<details class="topic" ${i===0?'open':''}><summary>${escapeHtml(q)}</summary><p>${escapeHtml(a)}</p></details>`).join('')}</div></div><div class="card"><h3>Reliable information</h3><p class="small-text" style="margin-top:7px">Further reading from established UK health organisations:</p><div class="source" style="margin-top:13px"><div>🔗 <a href="https://www.nhs.uk/conditions/high-cholesterol/" target="_blank" rel="noopener noreferrer">NHS — High cholesterol</a></div><div>🔗 <a href="https://www.nhs.uk/conditions/high-cholesterol/how-to-lower-your-cholesterol/" target="_blank" rel="noopener noreferrer">NHS — How to lower cholesterol</a></div><div>🔗 <a href="https://www.nhs.uk/conditions/high-cholesterol/getting-tested/" target="_blank" rel="noopener noreferrer">NHS — Getting tested</a></div><div>🔗 <a href="https://www.heartuk.org.uk/cholesterol/what-is-cholesterol" target="_blank" rel="noopener noreferrer">HEART UK — What is cholesterol?</a></div><div>🔗 <a href="https://www.nice.org.uk/guidance/ng238" target="_blank" rel="noopener noreferrer">NICE NG238 — Risk assessment and lipid modification</a></div></div></div></div><div class="col-stack"><div class="card"><div class="stat-icon mint">${ic('shield',25)}</div><h3>No symptoms doesn't mean no risk</h3><p class="small-text" style="margin-top:9px">Many people with raised cholesterol feel completely well. Ask a pharmacist or GP whether cholesterol testing is appropriate for you.</p><div class="hr"></div><h3>Follow through on results</h3><p class="small-text" style="margin-top:8px">Lipid measurements are interpreted alongside blood pressure, age, family history, smoking status, existing conditions and other relevant factors.</p></div><div class="callout"><strong>This is education, not medical advice</strong><p>HeartSteps does not perform blood tests, identify abnormal cholesterol, estimate individual cardiovascular risk or recommend prescriptions. For emergencies call 999 in the UK.</p></div></div></div>`;}
function settingsPage(){return `<div class="page-header"><div class="page-kicker">Your preferences</div><h1>Make HeartSteps your own.</h1><p>Choose a practical movement goal, export your progress or clear the demo. No account is required.</p></div><div class="settings-grid"><div class="card"><h3>My profile</h3><p class="small-text" style="margin:7px 0 18px">Only your chosen name and age are kept locally. Age is used to limit access to the community demo.</p><form id="profile-form"><div class="form-group"><label for="profile-name">Display name (optional)</label><input class="input" id="profile-name" name="name" maxlength="35" value="${escapeHtml(state.profile.name)}" placeholder="How should we greet you?"></div><div class="input-row"><div class="form-group"><label for="profile-age">Age (optional)</label><input class="input" id="profile-age" name="age" type="number" min="1" max="120" value="${state.profile.age??''}" placeholder="Years"></div><div class="form-group"><label for="profile-goal">Daily activity goal (minutes)</label><input class="input" id="profile-goal" name="goal" type="number" min="5" max="180" value="${state.profile.goal}" required></div></div><button class="btn" type="submit">${ic('check',15)} Save preferences</button></form></div><div class="card"><div class="stat-icon mint">${ic('lock',22)}</div><h3>Privacy & data</h3><p class="privacy-bullet">✅ Your entries stay in this browser's local storage.</p><p class="privacy-bullet">✅ Nothing is sent to Heart on Wheels, the NHS or an external service.</p><p class="privacy-bullet">✅ You choose whether to download or show a report.</p><p class="privacy-bullet">⚠️ Local browser storage is <strong>not encrypted clinical storage</strong>. Avoid entering real sensitive patient information.</p><div class="button-row">${btn(`${ic('download',16)} Export my progress`,'export','btn outline')}${btn('Clear all my data','reset','btn danger')}</div></div><div class="card"><h3>🎬 For your university demonstration</h3><p class="small-text" style="margin-top:9px">Fill the app with clearly labelled fictional entries to show the activity chart, streak, food-swap log and group challenge in a presentation.</p><div class="button-row">${btn('Load fictional example data','seed-demo','btn')}${state.demo?btn('Clear example data','clear-demo','btn outline'):''}</div><p class="notes" style="margin-top:12px">Example mode replaces current local data after confirmation. Export first if you wish to keep your entries.</p></div><div class="card"><h3>How this prototype works</h3><p class="small-text" style="margin-top:10px"><strong>Working now:</strong> food-swap suggestions, activity challenges, XP, streaks, medication checklist, alcohol tracker, private journal, and downloadable progress files.</p><p class="small-text" style="margin-top:10px"><strong>Proposed future features:</strong> secure AI integration, live group community, regulated/clinically reviewed workflows, robust reminders and appropriately authorised NHS interoperability.</p>${info('For real-world clinical deployment the app would require professional review, security testing, a data-protection assessment and appropriate regulatory evaluation.')}</div></div>`;}
function render(){let content;switch(view){case 'food':content=foodPage();break;case 'activity':content=activityPage();break;case 'meds':content=medsPage();break;case 'community':content=communityPage();break;case 'learn':content=learnPage();break;case 'settings':content=settingsPage();break;default:content=dashboard();}document.getElementById('app').innerHTML=shell(content);}
function navigate(to){if(!routes.some(r=>r[0]===to))return;view=to;render();window.scrollTo({top:0,behavior:'instant'});}
function downloadJSON(){const payload={exported_at:new Date().toISOString(),project:'HeartSteps (Heart on Wheels) student prototype',notice:'Locally generated record. Not a clinical document or NHS record.',data:state};const content=JSON.stringify(payload,null,2);const blob=new Blob([content],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`HeartSteps-progress-${today()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);notify('Progress file generated on your device.');}
function sampleData(){const d=defaults();d.profile={name:'Alex',age:32,goal:30};d.demo=true;const sample=[{offset:6,m:15,type:'Walking'},{offset:5,m:25,type:'Cycling'},{offset:4,m:20,type:'Walking'},{offset:3,m:35,type:'Dancing'},{offset:2,m:18,type:'Walking'},{offset:1,m:30,type:'Cycling'},{offset:0,m:20,type:'Walking'}];d.activity=sample.map((a,i)=>({id:`sample-act-${i}`,date:daysBefore(a.offset),type:a.type,minutes:a.m,note:'Fictional demo entry',xp:a.m*2}));d.food=[{id:'sample-food-1',date:daysBefore(3),from:'Butter',to:'Rapeseed oil spread'},{id:'sample-food-2',date:daysBefore(1),from:'Bacon',to:'Beans and lentils'},{id:'sample-food-3',date:today(),from:'Pastries',to:'Porridge with fruit'}];d.community.joined=true;return d;}
function handleAction(action){if(action.startsWith('nav:'))return navigate(action.slice(4));if(action.startsWith('quest:')){const q=quests.find(v=>v.id===action.slice(6));if(!q)return;return mutate(()=>state.activity.push({id:randId(),date:today(),type:q.type,minutes:q.minutes,note:`${q.name} — mini-challenge`,xp:q.xp}),`${q.minutes} minutes logged. +${q.xp} XP!`);}
if(action==='clear-swap'){swap=null;foodQuery='';return render();}if(action==='save-swap'){if(!swap)return;const s=swap;mutate(()=>state.food.push({id:randId(),date:today(),from:s.from,to:s.to}),'+10 XP — food swap choice saved!');return;}
if(action.startsWith('delete-food:'))return mutate(()=>{state.food=state.food.filter(x=>x.id!==action.slice(12));},'Food swap removed.');
if(action.startsWith('delete-activity:'))return mutate(()=>{state.activity=state.activity.filter(x=>x.id!==action.slice(16));},'Activity removed.');
if(action.startsWith('delete-alcohol:'))return mutate(()=>{state.alcohol=state.alcohol.filter(x=>x.id!==action.slice(15));},'Entry removed.');
if(action.startsWith('delete-note:'))return mutate(()=>{state.community.notes=state.community.notes.filter(x=>x.id!==action.slice(12));},'Private note deleted.');
if(action.startsWith('toggle-med:')){const id=action.slice(11);return mutate(()=>{const m=state.meds.find(m=>m.id===id);if(!m)return;m.takenDates=Array.isArray(m.takenDates)?m.takenDates:[];m.takenDates=m.takenDates.includes(today())?m.takenDates.filter(d=>d!==today()):[...m.takenDates,today()];},'Checklist updated. Follow your prescription instructions.');}
if(action.startsWith('delete-med:')){if(!confirm('Remove this medicine reminder? This does not change your prescription.'))return;return mutate(()=>{state.meds=state.meds.filter(m=>m.id!==action.slice(11));},'Medicine reminder removed.');}
if(action==='community-join')return mutate(()=>{state.community.joined=!state.community.joined;},state.community.joined?'You joined the illustrative challenge.':'You left the challenge.');
if(action.startsWith('community-tab:')){communityTab=action.split(':')[1];return render();}
if(action==='export')return downloadJSON();
if(action==='seed-demo'){if(!confirm('Replace current locally stored data with fictional sample entries? Export first if you want to save your own data.'))return;state=sampleData();swap=null;foodQuery='';save();navigate('dashboard');return notify('Fictional demo data loaded.');}
if(action==='clear-demo'||action==='reset'){if(!confirm('Clear all locally stored HeartSteps data? This cannot be undone.'))return;state=defaults();swap=null;foodQuery='';save();navigate(action==='reset'?'settings':'dashboard');return notify('Local data cleared.');}
}
function validDate(s){return typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&s>=daysBefore(90)&&s<=today()&&!Number.isNaN(fromDate(s).getTime());}
function handleForm(form){const data=new FormData(form);const id=form.id;
if(id==='food-form'){foodQuery=String(data.get('query')||'').trim().slice(0,85);if(foodQuery.length<2)return notify('Enter at least two characters.');swap=findSwap(foodQuery);return render();}
if(id==='activity-form'){const minutes=Number(data.get('minutes'));const date=String(data.get('date'));if(!Number.isInteger(minutes)||minutes<1||minutes>300||!validDate(date))return notify('Please enter 1–300 minutes and a date within the past 90 days.');const type=String(data.get('type')).slice(0,35);const note=String(data.get('note')||'').trim().slice(0,110);const xp=clamp(minutes*2,2,120);return mutate(()=>state.activity.push({id:randId(),date,type,minutes,note,xp}),`${minutes} minutes logged. +${xp} XP!`);}
if(id==='alcohol-form'){const units=Number(data.get('units')),date=String(data.get('date'));if(!Number.isFinite(units)||units<=0||units>100||!validDate(date))return notify('Enter valid units and a date within the past 90 days.');return mutate(()=>state.alcohol.push({id:randId(),date,units:Math.round(units*10)/10}),'Alcohol units recorded privately.');}
if(id==='med-form'){const name=String(data.get('name')||'').trim().slice(0,70),time=String(data.get('time')||'');if(!name||!/^([01]\d|2[0-3]):[0-5]\d$/.test(time))return notify('Enter a medicine name and a valid time.');return mutate(()=>state.meds.push({id:randId(),name,time,takenDates:[]}),`Reminder for ${name} added.`);}
if(id==='community-age-form'){const age=Number(data.get('age'));if(!Number.isInteger(age)||age<1||age>120)return notify('Please enter your age.');return mutate(()=>{state.profile.age=age;},age<25?'Community demo requires age 25 or over.':'Community demo unlocked.');}
if(id==='journal-form'){if(!(Number(state.profile.age)>=25))return notify('Community feature is age 25+.');const note=String(data.get('note')||'').trim().slice(0,500);if(note.length<2)return notify('Write at least a few words.');return mutate(()=>state.community.notes.push({id:randId(),date:today(),text:note}),'Private journal entry saved on this device.');}
if(id==='profile-form'){const name=String(data.get('name')||'').trim().slice(0,35),ageText=String(data.get('age')||'').trim(),age=ageText===''?null:Number(ageText),goal=Number(data.get('goal'));if(age!==null&&(!Number.isInteger(age)||age<1||age>120))return notify('Age must be between 1 and 120.');if(!Number.isInteger(goal)||goal<5||goal>180)return notify('Choose a daily goal from 5 to 180 minutes.');return mutate(()=>{state.profile={name,age,goal};},'Your preferences have been saved locally.');}
}
document.addEventListener('click',e=>{const target=e.target.closest('[data-nav],[data-action],[data-food-example]');if(!target)return;if(target.hasAttribute('data-nav')){navigate(target.getAttribute('data-nav'));return;}if(target.hasAttribute('data-food-example')){foodQuery=target.getAttribute('data-food-example');swap=findSwap(foodQuery);render();return;}const action=target.getAttribute('data-action');if(action)handleAction(action);});
document.addEventListener('submit',e=>{if(!e.target.matches('form'))return;e.preventDefault();handleForm(e.target);});
render();
})();
